// ZigZag算法(Z字填二维数组)
#include <stdio.h>
// 1. 扩展矩阵
#define MAX 1000  // 假设矩阵最大不超过500行,MAX用于标识扩展后矩阵最大行数为1000行 
int arr[MAX][MAX];

int main() {
    int i,j,n;
    scanf("%d",&n);
    for(i=0;i<n;i++){
       for(j=0;j<n;j++){
           scanf("%d",&arr[i][j]);
       }
    }         
    // num用于表示对角线个数 
    int num=2*n-1;
    // x和y表示当前位置 
    int x=0,y=0; 
    for(i=0;i<num;i++){
         // 1. 对角线索引为偶数,则沿右上方向遍历 
         if(i%2==0){
            // 超过原矩阵大小的区域不进行输出        
               while(x>0){
                 if(x<n && y<n) printf("%d ",arr[x][y]);     
                 x--,y++;
               }
               if(y<n) printf("%d ",arr[x][y]);
               y++;        
          }else{
            // 2. 对角线索引为奇数,则沿左下方向遍历
                  while(y>0){
                     if(x<n && y<n)  printf("%d ",arr[x][y]);
                     x++,y--;
                   }
                   if(x<n) printf("%d ",arr[x][y]);
                   x++;                 
         } 
   } 
   return 0;
}

