// 计算p在n!中贡献的指数 ， 依次计算 p , p^2 , p^3 在n中的出现次数
// 与快速幂做区分
int calExp(int n,int p){
   int exp=0 , power=p;
   while(power<=n){
      exp+=n/power;
      power*=p;
   }
   return exp;
}

int main(){
   int n;
   scanf("%d",&n);
   if(n<2){
      printf("1");
      return 0;
   }
   screen();
   int i,first=1;
   for(i=2;i<=n;i++){
      if(map[i]==0) continue;
      int exp = calExp(n,i);
      if(exp==0) continue;
      if(first!=1) putchar('*');
      first=0;
      if(exp==1) printf("%d",i);
      else printf("%d^%d",i,exp);
   }
   return 0; 
}
