// 1. power状态为: p , p^2 , p^4 ...
// 2. exp += n/power
int calExp(int n,int p){
    int power=p,exp=0;
    while(power<=n){
        exp+=n/power;
        power*=p;
    }
    return exp;
}

int main(){
   int n;
   scanf("%d",&n);
   screen(); 
   // 小于等于n即可
   for(int i=2;i<=n;i++){
      if(map[i]==0) continue;
      int exp = calExp(n,i);
      if(exp==0) continue;
      printf("%d %d\n",i,exp); 
   } 
   return 0; 
}

// 分解质因数
#include <stdio.h>
#include <math.h>

int prime(int n){
  // 不然逻辑不对！！！
  if(n<=1) return 0;
  int sn=sqrt(n);
  for(int i=2;i<=sn;i++){
      if(n%i==0) return 0;
  }
  return 1;  
}

int main(){
  int n;
  scanf("%d",&n);
  if(prime(n)){ // 本身已经是质数了，直接打印自身返回即可
      printf("%d",n);
      return 0;
  }
  int sn = sqrt(n);  
  for(int i=2;i<=sn;i++){
      while(n%i==0){
          printf("%d",i);
          n/=i;
          if(n>1) putchar(' ');
      }
      // 连续除完后,需要判断是否进入边界条件
      if(n==1) break;
      else if(prime(n)){
          printf("%d",n);
          break;
      }
  }
  return 0;
}
#include <stdio.h>
#include <string.h>

#define N 1000001
int map[N] = {0}; // 用于标记是否为素数

// 使用埃拉托色尼筛法生成素数表
void sieve() {
    map[0] = map[1] = 1; // 0 和 1 不是素数
    for (int i = 2; i * i < N; i++) {
        if (map[i] == 0) { // 如果 i 是素数
            for (int j = i * i; j < N; j += i) {
                map[j] = 1; // 标记 i 的倍数为非素数
            }
        }
    }
}

int main() {
    int n;
    scanf("%d", &n);

    if (n <= 1) {
        printf("1"); // 特殊情况：n = 1
        return 0;
    }

    sieve(); // 生成素数表

    // 输出质因数分解结果
    int first = 1; // 用于控制输出格式，避免多余空格
    for (int i = 2; i <= n; i++) {
        while (n % i == 0) { // 这里要确保 i 是 n 的因数
            if (!first) putchar(' '); // 如果不是第一个质因数，输出空格
            printf("%d", i);
            n /= i;
            first = 0; // 标记已经输出过质因数
        }
        if (n == 1) break; // 如果 n 已经被完全分解，则退出循环
    }

    return 0;
}
