// 区间合并
#include <stdio.h>

typedef struct{
   int x,y;
}Node;

int cmp(const void *a,const void *b){
   Node n1 = *(Node*)a , n2 = *(Node*)b;
   return n1.x-n2.x; // 左区间升序 
}

int main(){
  int i,n;
  scanf("%d",&n);
  Node arr[n];   // 结构体和int一样，都是直接拷贝的 ！！！
  for(i=0;i<n;i++){
     scanf("%d %d",&arr[i].x,&arr[i].y);
  }
  qsort(arr,n,sizeof(Node),cmp); 
  int rMax=arr[0].y,count=1;
  for(i=1;i<n;i++){
    if(rMax>=arr[i].x) rMax=rMax>arr[i].y ? rMax : arr[i].y;
    else{
        rMax = arr[i].y;
        count++;
    }  
  }
  printf("%d",count);  
  return 0;   
}

// 旋转矩阵
#include <stdio.h>

// 旋转函数
void rotate(int n, int arr[n][n], int x0, int y0, int x1, int y1, int 
direction) {
    // 检查子矩阵是否为方阵
    if (x1 - x0 != y1 - y0) {
        printf("子矩阵不是方阵，无法旋转！\n");
        return;
    }

    // 1. 转置子矩阵
    for (int i = x0; i <= x1; i++) {
        int col = y0 + i - x0; // 对角线索引
        for (int j = y0; j < col; j++) { // 处理下三角
            int temp = arr[i][j];
            // 对称的坐标不再是: arr[j][i]了
            // ***难点: J = x0 + j - y0;  I = y0 + i - x0;
            arr[i][j] = arr[j - y0 + x0][i - x0 + y0];
            arr[j - y0 + x0][i - x0 + y0] = temp;
        }
    }

    // 2. 顺时针旋转：列镜像 (对每一行进行翻转)
    if (direction == 0) {
        for (int i = x0; i <= x1; i++) {
            int left = y0, right = y1;
            while (left < right) {
                int temp = arr[i][left];
                arr[i][left] = arr[i][right];
                arr[i][right] = temp;
                left++, right--;
            }
        }
    }

    // 3. 逆时针旋转：行镜像 (***对每一列进行翻转)
    else if (direction == 1) {
        for (int j = y0; j <= y1; j++) {
            int top = x0, bottom = x1;
            while (top < bottom) {
                int temp = arr[top][j];
                arr[top][j] = arr[bottom][j];
                arr[bottom][j] = temp;
                top++, bottom--;
            }
        }
    }
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);  // 读取矩阵大小和操作次数
    int arr[n][n];
    int start = 1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            arr[i][j] = start++;  // 初始化矩阵
        }
    }

    // 处理每个旋转操作
    for (int i = 0; i < m; i++) {
        int x, y, r, z;
        scanf("%d %d %d %d", &x, &y, &r, &z);  // 读取旋转参数
        int x0 = x - r - 1, y0 = y - r - 1;  // 计算子矩阵边界
        int x1 = x + r - 1, y1 = y + r - 1;

        // 检查边界是否合法
        if (x0 < 0 || y0 < 0 || x1 >= n || y1 >= n) {
            printf("子矩阵超出范围，无法旋转！\n");
            continue;
        }

        rotate(n, arr, x0, y0, x1, y1, z);  // 调用旋转函数
    }

    // 输出最终矩阵
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            printf("%d ", arr[i][j]);
        }
        printf("\n");
    }

    return 0;
}

