// 相乘
char* multiply(char* num1, char* num2) {
   int l1=strlen(num1) , l2=strlen(num2);
   int dp[l1+l2];
   memset(dp,0,sizeof(dp));
   int i,j; // 经典错误: 将j的初始化提到外面提前做了，内层不做了！！！！！！
   for(i=l1-1;i>=0;i--){
      for(j=l2-1;j>=0;j--){
         int x=l1-i-1,y=l2-j-1,a=num1[i]-'0',b=num2[j]-'0';
         int temp = a*b + dp[x+y];
         dp[x+y] = temp%10;
         dp[x+y+1] += temp/10;
      }
   }
   char* res = (char*)malloc(sizeof(char)*(l1+l2+1));
   memset(res,'\0',sizeof(char)*(l1+l2+1));
   int zeroFlag=1,ri=0;
   for(i=l1+l2-1;i>=0;i--){
      if(zeroFlag && i>0 && !dp[i]) continue;
      zeroFlag=0;
      res[ri++]=dp[i]+'0';
   }
   res[ri]='\0';
   return res;  
}
#include <stdio.h>
#define N 40000

int main(){
  char s1[N],s2[N],res[N+N];
  scanf("%s %s",s1,s2);
  int i, j, l1=strlen(s1)-1,l2=strlen(s2)-1;
  for(i=0;i<2*N;i++) res[i]='0';  
  for(i=l1;i>=0;i--){
      for(j=l2;j>=0;j--){
          int x=l1-i,y=l2-j,a=s1[i]-'0',b=s2[j]-'0';
          int temp = a*b + res[x+y]-'0'; // 记得加上当前位已经存在的进位
          res[x+y]=temp%10+'0';
          res[x+y+1]+=temp/10; //保存进位
      }
  }
  // 前导零 
  int zeroFlag=1,len=l1+l2+2;
  for(i=len;i>=0;i--){
      if(zeroFlag && i>0 && res[i]=='0') continue;
      zeroFlag=0;
      putchar(res[i]); 
  }  
  return 0;   
}

