#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(){
  int n , count = 0;
  scanf("%d",&n);
  while(1){
    // 1. 翻转该数字
    int sum = 0 , temp = n;
    while(temp){
       sum = sum*10 + temp%10;
       temp/=10; 
    }
    // 2. 回文数: 反转后的数字和自身相等
    if(sum == n) break;
    // 3. 反转后的n和自身求和得新n
    n += sum;
    count++;   
  }
  printf("次数: %d, 回文数: %d",count,n); 
  return 0;
}

