#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#define N 100

void split(unsigned short a,unsigned short* pOdd,unsigned short* pEven){
   // 1. 利用itoa将a转换为字符串         
   char aStr[N];
   itoa(a,aStr,10);
   int len = strlen(aStr);
   // 2. 从左向右分别取奇偶位
   *pOdd = *pEven = 0;
   int i = 0;
   // 还可以利用atoi将字符串直接解析为整数 
   for(;i<len;i++){
     if(i%2==0) *pOdd = *pOdd * 10 + aStr[i]-'0';
     else *pEven = *pEven * 10 + aStr[i]-'0';                                  
   } 
}


int main(){
  unsigned short a = 12345;
  unsigned short* pOdd = (unsigned short*)malloc(sizeof(unsigned short)); 
  unsigned short* pEven = (unsigned short*)malloc(sizeof(unsigned short)); 
  split(a,pOdd,pEven);
  printf("偶数: %d , 奇数: %d",*pOdd,*pEven);
  return 0;
}

