#include <stdio.h>

int dfs(int m,int n){  
  if(m==0) return 1;
  if(m<0 || n==0) return 0; // 盘子用完了 or 苹果不够放  
  // 一个盘子为空 + 都不能为空
  return dfs(m,n-1) + dfs(m-n,n);  
}

