// 整数划分
int map[60][60];

int dfs(int n,int level){
   // 两种情况: n==0 or n==1
   // n==0 情况为 : 4-4 刚好划分完，那么最后返回 1 即可
   if(n<=1) return 1; 
   if(map[n][level]!=0) return map[n][level];
   // 做选择
   // 注意点: 第一层不能选择10，因为题目要求拆分为大于2个整数和
   // 后续层可以直接划分完 ！！！
   int max = 1 , len = level == 0 ? n-1 : n;
   for(int i=1;i<=len;i++){
       int res = dfs(n-i,level+1) * i;
       max = max > res ? max : res;
   }
   return map[n][level] = max;   
}

int integerBreak(int n) {
   memset(map,0,sizeof(map));
   return dfs(n,0);
}
int integerBreak(int n) {
   if(n==2) return 1;
   if(n==3) return 2;
   int p = n/3;
   int q = n%3;
   int res = pow(3,p);
   if(q==0) return res;
   else if(q==1) return res/3*4;
   return res * 2;
}
