   int max1 = 1;
    // i<=n-1因为第一层必须拆分为大于2个整数之和
   //  但是后续层并没有这个要求，因此我们在第一层就直接考虑i*(n-i)这个选择
   //  这样后续层不再拆分的情况，在其上一层就已经考虑到了，因此后续层就可以遵循同样的判断
逻辑了！
   for(int i=1;i<=n-1;i++){
      // 每个数继续拆 or 不拆
      max1=max(max1,dfs(n-i)*i,i*(n-i)); 
   }
   return map[n]=max1; 
}

int integerBreak(int n) {
    memset(map,0,sizeof(map));
    return dfs(n);
}
int max(int a,int b,int c){
    if(a<b) a=b;
    if(a<c) a=c;
    return a;
}

int integerBreak(int n) {
    int dp[60]={0};
    dp[0] = dp[1] = dp[2] = 1;
    for(int i=3;i<=n;i++) // 不断递推状态
      // 做选择 -- 第一层必须划分大于为两个整数，因此为了统一判断逻辑，将后续层完全划分的
逻辑
      // 提前到上一层进行判断
      for(int j=1;j<i;j++) dp[i] = max(dp[i],dp[i-j]*j,j*(i-j));
    return dp[n];
}

// 最大约数和
#include <stdio.h>

// 计算p的因子和 -- 完数 ！！！
int ys(int p) {
    int s1 = 0;
    for (int j = 1; j < p; j++) { // 真约数（不包括自己）
        if (p % j == 0) {
            s1 += j;
        }
    }
    return s1;
}

int main() {
    int s;
    scanf("%d", &s); // 输入 s

    int a[1001], b[1001]; // a: 数字（重量），b: 真约数和（价值）
    for (int i = 1; i <= s; i++) {
        b[i] = ys(i); // 计算真约数和
        a[i] = i;      // 数字本身作为重量
    }

    // 二维 DP 数组：dp[i][j] 表示前 i 个数，总重量不超过 j 的最大价值
    int dp[1001][1001] = {0};

    for (int i = 1; i <= s; i++) {      // 遍历数字（物品）
        for (int j = 1; j <= s; j++) {   // 遍历容量（总重量）
            if (a[i] > j) {
                // 当前数字太大，不能选
                dp[i][j] = dp[i - 1][j];
            } else {
                // 可以选或不选，取最大值
                dp[i][j] = (dp[i - 1][j] > dp[i - 1][j - a[i]] + b[i]) 
                          ? dp[i - 1][j] 
                          : dp[i - 1][j - a[i]] + b[i];
            }
        }
    }

    printf("%d\n", dp[s][s]); // 输出最大真约数和
    return 0;
}

