    int maxIndex = 0; // 记录最长公共子串在 s1 中的起始位置

    // 暴力匹配：从 s2 的每个位置开始，与 s1 的所有位置逐一匹配
    for (int i = 0; i < l2; i++) { // 遍历 s2 的每个起始位置
        for (int j = 0; j < l1; j++) { // 遍历 s1 的每个位置
            int k = 0;
            while (i + k < l2 && j + k < l1 && s2[i + k] == s1[j + k]) {
                k++; // 匹配长度增加
            }
            if (k > maxLen) { // 更新最长公共子串的信息
                maxLen = k;
                maxIndex = j;
            }
        }
    }

    // 输出最长公共子串
    for (int i = 0; i < maxLen; i++) {
        putchar(s1[maxIndex + i]);
    }
    return 0;
}
#include <stdio.h>
#include <string.h>
