void dfs(int i, int j, int curLen) {
    // 如果当前匹配长度大于最大值，更新最大值
    if (curLen > maxLen) {
        maxLen = curLen;
        maxIndex = i - curLen;
    }

    // 如果遍历到字符串末尾，返回
    if (i == l1 || j == l2) return;

    // 如果当前字符匹配，继续递归匹配下一个字符
    if (s1[i] == s2[j]) {
        dfs(i + 1, j + 1, curLen + 1);
    } else {
        // 如果当前字符不匹配，分别尝试跳过 s1[i] 或 s2[j]
        dfs(i + 1, j, 0); // 跳过 s1[i]
        dfs(i, j + 1, 0); // 跳过 s2[j]
    }
}

int main() {
