// 最长连续字符
#include <stdio.h>
#define N 300

void f(char *s) {
    int len = strlen(s);
    if (len == 0) return;

    char cur = s[0], maxCur = s[0];
    int count = 1, max = 1;

    // 遍历字符串
    for (int i = 1; i < len; i++) {
        if (s[i] == cur) {
            count++;
        } else {
            // 更新最大值
            if (count > max) {
                max = count;
                maxCur = cur;
            }
            // 重置当前字符和计数
            cur = s[i];
            count = 1;
        }
    }

    // 单独处理字符串末尾: 最后一段连续字符的更新
    if (count > max) {
        max = count;
        maxCur = cur;
    }

    printf("%c %d\n", maxCur, max);
}

int main(){
