// 素数环(美丽的项链)
#include <stdio.h>
#include <string.h>

#define N 20
#define NUM 40 // 最大和为 2 * n，因此只需筛选到 2 * n

int ans[N];     // 存储当前排列
int visit[N];   // 标记数字是否已被使用
int map[NUM];   // 素数表，0 表示素数，1 表示非素数
int n;          // 输入的数字 n

// 筛选法预求解素数
void screen() {
    memset(map, 0, sizeof(map));
    map[0] = map[1] = 1; // 1 表示非素数，0 表示素数
    int i,j;
    for (i= 2; i * i < NUM; i++) {
        if (map[i]) continue;
        for (j = i * i; j < NUM; j += i) {
            map[j] = 1;
        }
    }
}

// 深度优先搜索
void dfs(int i) {
    // 如果已经填满 n 个数字
    if (i == n + 1) {
        // 检查首尾数字之和是否为素数
        if (map[ans[1] + ans[n]]) return;
        // 输出当前排列
        int j;
        for (j = 1; j <= n; j++) {
            printf("%d ", ans[j]);
        }
        putchar('\n');
        return;
    }

    // 尝试将数字 j 放在第 i 个位置
    int j;
    for (j = 1; j <= n; j++) {
        if (visit[j]) continue; // 如果数字 j 已被使用，则跳过
        if (i > 1 && map[ans[i - 1] + j]) continue; // 如果与前一个数字之和不是素
数，则跳过

        // 做选择
        visit[j] = 1;
        ans[i] = j;

        // 递归
        dfs(i + 1);

        // 撤销选择
        visit[j] = 0;
    }
}

// 下标统一从1开始！！！
int main() {
    screen(); // 预处理素数表

    while (scanf("%d", &n) == 1) {
        memset(visit, 0, sizeof(visit)); // 初始化标记数组
        // 输出时，从整数 1 开始逆时针排列。
        visit[1] = 1; // 固定第一个数字为 1
        ans[1] = 1;   // 第一个数字为 1
        dfs(2);       // 从第 2 个位置开始搜索
    }

    return 0;
}

// 蛇形填数字(ZigZag)
#include <stdio.h>
#define N 20
int arr[N][N]; // 扩展矩阵

int main(){
  int n;
  scanf("%d",&n);
  int num = 2*n-1; // 对角线数量
  int x=0,y=0,index=1; // 起点坐标和填充的数字起始值 
  for(int i=0;i<num;i++){
      if(i%2==0){ // 对角线索引为偶数，则遍历方向为从左下到右上
          while(x>0){
              if(x<n && y<n) arr[x][y]=index++;
              x--,y++;
          }
          // x=0单独处理
          if(y<n) arr[x][y]=index++;
          y++; // 移动到下一条对角线起点
      }else{ // 对角线为奇数,则遍历方向为从右上到左下
          while(y>0){
              if(x<n && y<n) arr[x][y]=index++;
              x++,y--;
          }
          // y=0单独处理
          if(y<n) arr[x][y]=index++;
          x++; // 移动到下一条对角线起点
      }
  }
  // 输出arr
  for(int i=0;i<n;i++){
      for(int j=0;j<n;j++){
          printf("%d ",arr[i][j]);
      }
      putchar('\n');
  }  
}

