   if(map[si][sj]==1) return 0; // 已访问过或遇到障碍物 
   if(si==fi && sj==fj) return 1; // 找到一条路径
   map[si][sj] = 1; // 将当前合法且已经访问过的位置设置为障碍物
   // 尝试上下左右四个方向
   int sum = 0;
   // 向下探索的过程中，将走过的路径设置为障碍物，但是当前路径探索完毕返回时，将来时的路依
次恢复
   // 不同路径的探索过程是独立的，不应该受对方影响
   // 如果返回阶段，不及时撤销以访问状态，那么便会影响其他路径的探索过程
   sum += dfs(n,m,si-1,sj,fi,fj);
   sum += dfs(n,m,si+1,sj,fi,fj);
   sum += dfs(n,m,si,sj+1,fi,fj);
   sum += dfs(n,m,si,sj-1,fi,fj);
   map[si][sj] = 0; // 恢复合法状态
   return sum; 
}

