int lengthOfLongestSubstring(char* s) {
    int map[128] = {0}; // 标记某个字符是否已在滑动窗口中出现
    int b = 0, e = 0; // 滑窗的开始和结束位置
    int max = 0; // 记录无重复最长子串长度
    int num = 0; // 当前窗口内字符个数

    while(e < strlen(s)) {
        char in = s[e++];
        map[in]++; 
        num++;
        // 若in字符重复，则不断移动b指针，直到窗口内in字符个数为1
        while(map[in] > 1) {
            char out = s[b++];
            num--;
            map[out]--;
        }
        // 当前滑窗已不含重复字符，判断是否产生了更长的无重复子串
        if(num > max) max = num;
    }
    return max;
}

