// 解决办法: 4为死亡对象(当前时刻存活),6为存活对象(当前时刻死亡)
void gameOfLife(int** board, int boardSize, int* boardColSize) {
    for(int i=0;i<boardSize;i++){
       for(int j=0;j<boardColSize[i];j++){
            int aliveNum = f(board,boardSize,boardColSize[i],i,j);
            // 判断当前细胞是否会死亡
            if(board[i][j]==1){
               if(aliveNum<2 || aliveNum>3) board[i][j]=4;   
            }else{
            // 判断当前细胞是否会死而复生
               if(aliveNum==3) board[i][j]=6;   
            }
       }
    }
    // 将4和6解码为0和1
    for(int i=0;i<boardSize;i++){
        for(int j=0;j<boardColSize[i];j++){
            if(board[i][j]==4) board[i][j]=0;
            if(board[i][j]==6) board[i][j]=1;
        }
    }
}

