// 计算两个向量的欧氏距离
double euclideanDistance(double* a, double* b, int n) {
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        double diff = a[i] - b[i];
        sum += diff * diff;
    }
    return sqrt(sum);
}

// 计算矩阵 A 和矩阵 B 的欧氏距离矩阵 C
// 矩阵A和矩阵B的行数可以不同，但是列数必须相同
double** euclideanDistanceMatrix(double** A, double** B, int rowsA, int rowsB, 
int cols) {
    double** C = allocateMatrix(rowsA, rowsB); // 最终得到的矩阵C维度为: 
[rowsA,rowsB]
    for (int i = 0; i < rowsA; i++) {
        for (int j = 0; j < rowsB; j++) {
            C[i][j] = euclideanDistance(A[i], B[j], cols);
        }
    }
    return C;
}

