// 动态规划法
char* longestPalindrome(char* s) {
   int len = strlen(s);
   // dp[i][j] 表示i~j区间是否为回文区间
   // 易错点: 一定记得初始化！！！
   bool dp[N][N]={false}; 
   // 在所有回文区间中找到最大的区间
   int ml=0,mr=0;
   for(int i=0;i<len;i++){
      for(int j=0;j<=i;j++){
         // 定位每一个区间: j~i
        // 外围两个字符相等
        if(s[i]==s[j] &&
        // 当前j~i区间内字符个数少于等于2个
        // j+1 ~ i-1 区间本身也为回文区间
        (i-j<=1 || dp[j+1][i-1])){
            dp[j][i] = true;
            if((mr-ml)<(i-j)){
                mr=i;
                ml=j;
            }            
        }
      }
   }
   // copy最长的回文子串然后返回
   // 易错点: 一定要多一个字符空间存放'\0'
   char *res = (char*)malloc(sizeof(char)*(mr-ml+2));
   for(int i=0;i<(mr-ml+1);i++){
       res[i] = s[ml+i];
   }
   // 一定不要忘记设置'\0'
   res[mr-ml+1]='\0';
   return res;
}
// 中心扩散法
int ml,mr;

void cal(char* s,int i,int j){
    int len = strlen(s);
    while(i>=0 && j<len){
        if(s[i]!=s[j]) break;
        if((j-i)>(mr-ml)){
            mr=j;
            ml=i;
        }
        i--,j++;
    }
}

