删除C语言文件中的注释(状态机)
#include <stdio.h>

enum State { COMMON, ONE_LINE, MUTIL_LINE, CHAR, STR };

int main() {
    FILE *in_fp, *out_fp;
    in_fp = fopen("in.txt", "r");
    if (in_fp == NULL) {
        perror("无法打开输入文件");
        return 1;
    }

    out_fp = fopen("out.txt", "w");
    if (out_fp == NULL) {
        perror("无法打开输出文件");
        fclose(in_fp);
        return 1;
    }

    char c;
    enum State flag = COMMON;

    while ((c = fgetc(in_fp)) != EOF) {
        switch (flag) {
            // 普通状态
            case COMMON:
                // 判断是否为单行，多行注释开头 或 正常字符 
                if (c == '/') {
                    char next_char = fgetc(in_fp);
                    if (next_char == '/') {
                        flag = ONE_LINE;
                    } else if (next_char == '*') {
                        flag = MUTIL_LINE;
                    } else {
                        fprintf(out_fp, "/%c", next_char);
                    }
                // 判断是否为字符开头    
                } else if (c == '\'') {
                    fputc(c, out_fp);
                    flag = CHAR;
                // 判断是否为字符串开头    
                } else if (c == '\"') {
                    fputc(c, out_fp);
                    flag = STR;
                // 正常字符    
                } else {
                    fputc(c, out_fp);
                }
                break;
            // 单行注释    
            case ONE_LINE:
                // 换行符表明单行注释范围结束
                if (c == '\n') {
                    fputc('\n', out_fp);
                    flag = COMMON;
                }
                break;
            // 多行注释    
            case MUTIL_LINE:
                // 判断多行注释是否结束
                if (c == '*') {
                    char next_char = fgetc(in_fp);
                    if (next_char == '/') {
                        flag = COMMON;
                        fputc('\n', out_fp);
                    }
                }
                break;
            // 字符    
            case CHAR:
                // 字符范围结束 ?
                fputc(c, out_fp);
                if (c == '\\') {
                    char next_char = fgetc(in_fp);
                    fputc(next_char, out_fp);
                } else if (c == '\'') flag = COMMON;
                break;
            // 字符串    
            case STR:
                // 字符串范围结束 ？
                fputc(c, out_fp);
                if (c == '\\') {
                    char next_char = fgetc(in_fp);
                    fputc(next_char, out_fp);
                } else if (c == '\"') flag = COMMON;
                break;
        }
    }

    fclose(in_fp);
    fclose(out_fp);
    return 0;
}

交换链表中的节点
typedef struct ListNode* NodeP;
typedef struct ListNode Node;

struct ListNode* swapNodes(struct ListNode* head, int k) {
    NodeP dummyNode = (NodeP)malloc(sizeof(Node));
    dummyNode->next=head;
    NodeP p=dummyNode,q=dummyNode;
    int step = k;
    while(--step>=0) p=p->next;
    while(p){
        p=p->next;
        q=q->next;
    }
    p=dummyNode;
    step = k;
    while(--step>=0) p=p->next;
    int temp = p->val;
    p->val = q->val;
    q->val = temp;
    return dummyNode->next;    
}

两两交换链表中的节点
typedef struct ListNode* NodeP;
typedef struct ListNode Node;

struct ListNode* swapPairs(struct ListNode* head) {
    NodeP dummyNode = (NodeP)malloc(sizeof(Node));
    dummyNode->next = head;
    NodeP cur=dummyNode;
    while(cur && cur->next && cur->next->next){
        NodeP p = cur->next;
        NodeP q = p->next;
        NodeP next = q->next;
        cur->next = q;
        q->next = p;
        p->next = next;
        cur = p;
    }
    return dummyNode->next;    
}
typedef struct ListNode* NodeP;
typedef struct ListNode Node;

struct ListNode* swapPairs(struct ListNode* head) {
    if(head==NULL || head->next==NULL) return head;
    NodeP next = head->next;
    head->next = swapPairs(next->next);
    next->next = head;
    return next;  
}
