TOP K
void swap(int* arr,int a,int b){
   int temp = arr[a];
   arr[a] = arr[b];
   arr[b] = temp;
}

void shiftDown(int* arr,int size,int root){
   int left = 2*root+1;
   int right = left+1;
   int maxIndex = root;
   if(left<size && arr[maxIndex] < arr[left]) maxIndex = left;
   if(right<size && arr[maxIndex] < arr[right]) maxIndex = right;
   if(maxIndex!=root){
       swap(arr,maxIndex,root);
       shiftDown(arr,size,maxIndex);
   }
}

void buildHeap(int* arr,int n){
  for(int i=n/2-1;i>=0;i--) shiftDown(arr,n,i);
}

int findKthLargest(int* nums,int numsSize,int k){
    buildHeap(nums,numsSize);
    for(int i=numsSize-1;i>=numsSize-k;i--){
         swap(nums,0,i);
         shiftDown(nums,i,0);
    }
    return nums[numsSize-k];     
}
void swap(int* arr,int a,int b){
   int temp = arr[a];
   arr[a] = arr[b];
   arr[b] = temp;
}

int quickSort(int* arr,int b,int e,int k){
    if(b>=e) return arr[b];
    int p=b,q=e;
    while(p<q){
       while(p<q && arr[p] < arr[q]) q--;
       if(p<q) swap(arr,p++,q);
       while(p<q && arr[p] < arr[q]) p++;
       if(p<q) swap(arr,p,q--);
    }
    if(p==k) return arr[p];
    else if(p>k) return quickSort(arr,b,q-1,k);
    return quickSort(arr,q+1,e,k);
}

int findKthLargest(int* nums,int numsSize,int k){
    return quickSort(nums,0,numsSize-1,numsSize-k);     
}

