int binsearch(char *word, struct key *keytab, int n)  
{
        int low = 0, high = n-1, mid;
        while(low <= high) {
                mid = (low + high)/2;
                if(strcmp(word, keytab[mid].wordstal) > 0)
                        low = mid + 1;
                else if(strcmp(word, keytab[mid].wordstal) < 0)
