// 冒泡排序
void sort(int* arr,int n){
  for(int i=0;i<n;i++){
    int flag=1; // 标记本轮是否产生了交换  
    for(int j=n-1;j>i;j--){
        if(arr[j]<arr[j-1]){
            int temp = arr[j];
            arr[j] = arr[j-1];
            arr[j-1] = temp;
            flag=0;
        }
    }
    if(flag) break;  
  }
}

