// 马的遍历 -- BFS最短路径
#include <stdio.h>
#include <string.h>
#define N 400
int map[N][N];
int queue[N*N][2];
int n,m;
// 马走日,即走L型,先横或竖走两步,再横或竖走一步
int dx[8] = {-1,-1,1,1,2,2,-2,-2};
int dy[8] = {-2,2,-2,2,-1,1,-1,1};

void bfs(int x,int y){
   map[x][y]=0;
   int head=0,tail=0,step=0,size=1;
   queue[tail][0]=x,queue[tail++][1]=y;
   while(head<tail){
      // 将当前层的所有节点出队后,层数加一,即step++
      int temp = size; 
      ++step,size=0;
      for(int k=0;k<temp;k++){
         int x1 = queue[head][0], y1 = queue[head++][1];
         // 做选择
         for(int i=0;i<8;i++){
           int tempx = x1 + dx[i], tempy = y1 + dy[i];
           if(tempx<0 || tempx>=n || tempy<0 || tempy>=m) continue; // 越界检测
           if(map[tempx][tempy]!=-1) continue; // 已经访问过！
           map[tempx][tempy] = step;
           queue[tail][0]=tempx,queue[tail++][1]=tempy;
           size++;  
         }    
      } 
   } 
}



int main(){
  int x,y;
  scanf("%d %d %d %d",&n,&m,&x,&y);
  memset(map,-1,sizeof(map));
  bfs(x-1,y-1);
  for(int i=0;i<n;i++){
      for(int j=0;j<m;j++){
          printf("%d ",map[i][j]);
      }
      putchar('\n');
  }
  return 0;  
}

