// 求逆序对的数量 (归并排序)
int mergeSort(int* record, int b, int e) {
    if (b >= e) return 0; // 单个元素或空区间，没有逆序对

    int m = (b + e) / 2;
    int count = mergeSort(record, b, m) + mergeSort(record, m + 1, e);

    int len = e - b + 1; // 定义临时数组大小
    int temp[len];
    int p = b, q = m + 1, i = 0;

    // 归并过程
    while (p <= m && q <= e) {
        // 取等逻辑不能放到else分支进行计算！！！
        if (record[p] <= record[q]) {
            temp[i++] = record[p++];
        } else {
            temp[i++] = record[q++];
            count += m - p + 1; // 统计逆序对数量
        }
    }

    // 将剩余的左半部分元素加入临时数组
    while (p <= m) {
        temp[i++] = record[p++];
    }

    // 将剩余的右半部分元素加入临时数组 , 没有必要计算逆序对了！！！
    while (q <= e) {
        temp[i++] = record[q++];
    }

    // 将临时数组的内容复制回原数组
    for (int j = 0; j < len; j++) {
        record[b + j] = temp[j];
    }

    return count;
}

int reversePairs(int* record, int recordSize) {
    return mergeSort(record, 0, recordSize - 1);
}

