        visit[j] = 0;
    }
}

void sort(int* arr,int n){
  int i,j;
  for(i=0;i<n;i++){
          int min=i;
          for(j=i;j<n;j++){
             if(arr[j]<arr[min]) min=j;
          }
          if(min!=i){
               int temp = arr[i];
               arr[i] = arr[min];
               arr[min] = temp;
          }
  }        
}

