// 第一个回合直接给第一个小朋友分两个糖果是重复的结果！
int dfs(int n, int limit, int start) {
    if (n == 0) return 1;
    int sum = 0;
    // 本轮尝试分配给三位小朋友中的一位，从 start 开始
    for (int i = start; i < 3; i++) {
        if (box[i] + 1 > limit) continue;
        box[i]++;
        sum += dfs(n - 1, limit, i);  // 从 i 开始，确保非递减顺序
        box[i]--;
    }
    return sum;
}

int distributeCandies(int n, int limit) {
    memset(box, 0, sizeof(box));
    return dfs(n, limit, 0);  // 从第 0 位小朋友开始
}

