#include <stdio.h>
#include <math.h>

// 硬币是偶数，没处理为奇数的情况
int f(int arr[10],int b,int e){
  if(abs(b-e)<=1) return arr[b] < arr[e] ? b : e;
  int m = (b+e)/2;
  int s1=0,s2=0,i=b,j=m+1;
  for(;i<=m;i++) s1+=arr[i]; 
  for(;j<=e;j++) s2+=arr[j];
  if(s1>s2) return f(arr,m+1,e);
  return f(arr,b,m);            
}

int main(){
  int arr[8]={10,10,10,10,10,10,10,6};
  int index = f(arr,0,7);
  printf("假币索引为: %d , 假币质量为: %d",index,arr[index]); 
  return 0;        
}
#include <stdio.h>

// 寻找假币的函数
int f(int arr[], int b, int e) {
    // 当只剩下一个元素时，直接返回该元素的索引
    if (b == e) {
        return b;
    }
    // 当只剩下两个元素时，返回较小元素的索引
    if (b + 1 == e) {
        return arr[b] < arr[e] ? b : e;
    }

    int m = (b + e) / 2;
    int s1 = 0, s2 = 0;
    int i;

    // 若硬币个数为奇数，拿出中间元素
    int middleCoinIndex = -1;
    if ((e - b + 1) % 2 != 0) {
        middleCoinIndex = m;
        m--; // 调整中间位置以平均分组
    }

    // 计算左半部分的重量和
    for (i = b; i <= m; i++) {
        s1 += arr[i];
    }
    // 计算右半部分的重量和
    for (i = m + 2; i <= e; i++) {
        s2 += arr[i];
    }

    if (s1 > s2) {
        // 假币在右半部分（不包含拿出的中间元素）
        return f(arr, m + 2, e);
    } else if (s1 < s2) {
        // 假币在左半部分
        return f(arr, b, m);
    } else {
        // 左右两部分重量相等，假币是拿出的中间元素
        if (middleCoinIndex != -1) {
            return middleCoinIndex;
        }
        // 理论上不会出现这种情况，但为了代码完整性添加
        return -1; 
    }
}

int main() {
    int arr[9] = {10, 10, 10, 10, 10, 10, 10, 10, 6};
    int index = f(arr, 0, 8);
    printf("假币索引为: %d , 假币质量为: %d", index, arr[index]);
    return 0;
}

