#include <stdio.h>
#include <string.h>
#include <math.h>

#define MAXN 1030

int match[MAXN][MAXN]; // 存储比赛日程表

// 左上复制到右下
void copyL(int x, int y, int l) {
    for (int i = x; i < x + l; i++) {
        for (int j = y; j < y + l; j++) {
            match[i + l][j + l] = match[i][j];
        }
    }
}

// 右上复制到左下
void copyR(int x, int y, int l) {
    for (int i = x; i < x + l; i++) {
        for (int j = y; j < y + l; j++) {
            match[i + l][j - l] = match[i][j];
        }
    }
}

// 分治法构造比赛日程表
void solve(int x, int y, int l) {
    if (l == 1) { // l表示边长
        return; // 递归终止条件：最小规模
    }

    // 递归解决左上角和右上角的子问题
    solve(x, y, l >> 1);                  // 左上角
    solve(x, y + (l >> 1), l >> 1);      // 右上角

    // 扩展到整个日程表
    copyL(x, y, l >> 1);                 // 左上复制到右下
    copyR(x, y + (l >> 1), l >> 1);      // 右上复制到左下
}

