    // 第 1 列表示其他选手与第 1 名选手的比赛安排。
    for (i = 1; i <= n; i++) {
        match[1][i] = i; // 第 1 行初始化
        match[i][1] = i; // 第 1 列初始化
    }

    // 调用分治法构造日程表
    solve(1, 1, n);

    // 输出比赛日程表
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            printf("%d ", match[i][j]); // 每个数字占两位宽度
        }
        printf("\n");
    }

