#define N 9

char** map;
int line[N][N + 1];  // 当前行是否已经存放了某个数字
int col[N][N + 1];   // 当前列是否已经存放了某个数字
int box[N / 3][N / 3][N + 1];  // 某个box内是否已经存放了某个数字

bool dfs(int i, int j) {
    if (i == N) return true;  // 所有行已处理完，找到解
    if (j == N) return dfs(i + 1, 0);  // 当前行所有列填充完毕，转到下一行，起始为
0！！！

    // 初态: 如果当前格子已经填充，直接处理下一个格子
    if (map[i][j] != '.') return dfs(i, j + 1);

    // 尝试填充数字 1 到 9
    for (int num = 1; num <= 9; num++) {
        if (line[i][num] || col[j][num] || box[i / 3][j / 3][num]) continue;

        // 填充数字
        map[i][j] = '0' + num;
        line[i][num] = 1;
        col[j][num] = 1;
        box[i / 3][j / 3][num] = 1;

        // 递归处理下一个格子 -- 找到唯一解直接返回
        if (dfs(i, j + 1)) return true;

        // 回溯
        map[i][j] = '.';
        line[i][num] = 0;
        col[j][num] = 0;
        box[i / 3][j / 3][num] = 0;
    }

    return false;  // 无解
}

void solveSudoku(char** board, int boardSize, int* boardColSize) {
    map = board;

    // 重置辅助数组 --- 不然全局状态会保留
    memset(line, 0, sizeof(line));
    memset(col, 0, sizeof(col));
    memset(box, 0, sizeof(box));

    // 初始化辅助数组 -- 存在初始状态
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (board[i][j] == '.') continue;
            int num = board[i][j] - '0';
            line[i][num] = 1;
            col[j][num] = 1;
            box[i / 3][j / 3][num] = 1;
        }
    }

    // 开始求解
    dfs(0, 0);
}

