// 定义棋盘大小
#define N 8

// 定义骑士的移动方向
int dx[8] = { -2, -1, 1, 2, 2, 1, -1, -2 };
int dy[8] = { 1, 2, 2, 1, -1, -2, -2, -1 };

// 打印解决方案
void printSolution(int path[N * N][2]) {
    for (int i = 0; i < N * N; ++i) {
        printf("(%d, %d) ", path[i][0], path[i][1]);
        if ((i + 1) % N == 0)
            printf("\n");
    }
}

// 检查位置是否在棋盘内且尚未访问过
bool isSafe(int board[N][N], int x, int y) {
    return (x >= 0 && x < N && y >= 0 && y < N && board[x][y] == -1);
}

// 使用回溯递归解决骑士之旅问题
bool solveKnightTour(int board[N][N], int path[N * N][2], int x, int y, int 
moveNum) {
    // 如果所有方格都已访问，则问题解决
    if (moveNum == N * N)
        return true;

    // 尝试骑士的所有移动方向
    for (int k = 0; k < 8; ++k) {
        int nextX = x + dx[k];
        int nextY = y + dy[k];

        if (isSafe(board, nextX, nextY)) {
            board[nextX][nextY] = moveNum; // 标记该位置为已访问
            path[moveNum][0] = nextX;      // 记录路径
            path[moveNum][1] = nextY;

            if (solveKnightTour(board, path, nextX, nextY, moveNum + 1))
                return true;

            board[nextX][nextY] = -1; // 回溯，将该位置标记为未访问
        }
    }

    return false;
}

int main() {
    // 初始化棋盘和路径
    int board[N][N];
    int path[N * N][2]; // 存储路径的二维数组

    // 初始化棋盘为 -1，表示未访问
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            board[i][j] = -1;

    // 设置起始位置
    int startX = 0;
    int startY = 0;

    // 将起始位置标记为已访问
    board[startX][startY] = 0;
    path[0][0] = startX;
    path[0][1] = startY;

    // 解决骑士之旅问题
    if (solveKnightTour(board, path, startX, startY, 1)) {
        printf("存在解决方案：\n");
        printSolution(path);
    } else {
        printf("不存在解决方案。\n");
    }

    return 0;
}

