int jump(int* nums, int numsSize) {
    int curEnd=0,count=0;
    for(int i=0;i<numsSize;i++){
        if(curEnd>=numsSize-1) break;
        // 遍历 i ~ curEnd 找出 nextEnd
        int nextEnd = curEnd;
        for(int j=i;j<=curEnd;j++){
            if(j+nums[j]>nextEnd) nextEnd = j + nums[j];
        }
        curEnd = nextEnd;
        count++;
    }
    return count;
}

加油站
int canCompleteCircuit(int* gas, int gasSize, int* cost, int costSize) {
    int sum=0,minSum=0,index=0;
    for(int i=0;i<gasSize;i++){
        sum += gas[i] - cost[i];
        if(sum<minSum){
            minSum = sum;
            // 经过第 i 个站点后，使 sum 到达新低
            // 所以站点 i + 1 就是最低点（起点）
            index = (i+1)%gasSize; // 下标从0开始
        }
    }
    if(sum<0) return -1;
    return index;
}

