#include <stdio.h>
#include <stdlib.h> // 引入 qsort 函数
#include <math.h>   // 引入数学库，用于处理浮点数精度

// 定义物品结构体
typedef struct {
    double weight;    // 重量
    double value;     // 价值
    double unit_value; // 单位价值
} Item;

// 比较函数：按单位价值降序排列
int compare(const void *a, const void *b) {
    Item *item1 = (Item *)a;
    Item *item2 = (Item *)b;
    // 负值 ：表示 a 应该排在 b 前面。
    // 0 ：表示 a 和 b 相等。
    // 正值 ：表示 a 应该排在 b 后面。
    if (item1->unit_value > item2->unit_value) return -1; // 单位价值高的排在前面
    if (item1->unit_value < item2->unit_value) return 1;  // 单位价值低的排在后面
    return 0;
}

int main() {
    int N;       // N堆金币
    double T;    // 背包承重量
    scanf("%d %lf", &N, &T);

    // 输入金币的重量和价值，并计算单位价值
    Item items[N];
    for (int i = 0; i < N; i++) {
        scanf("%lf %lf", &items[i].weight, &items[i].value);
        items[i].unit_value = items[i].value / items[i].weight; // 计算单位价值
    }

    // 使用 qsort 对物品按单位价值降序排列
    qsort(items, N, sizeof(Item), compare);

    // 执行贪心算法
    double res = 0;
    for (int i = 0; i < N; i++) {
        if (T >= items[i].weight) { // 如果背包能装下整个物品
            res += items[i].value;  // 累加价值
            T -= items[i].weight;   // 减少背包容量
        } else {                    // 如果只能装下部分物品
            res += T * items[i].unit_value; // 按比例累加价值
            break;
        }
    }

    // 输出结果
    printf("%.2lf\n", res); // 保留两位小数
    return 0;
}

