拓扑排序
bool canFinish(int numCourses, int** prerequisites, int prerequisitesSize, 
int* prerequisitesColSize) {
   int n=numCourses,m=prerequisitesSize,id[n]; // id为入度数组
   int map[n][n];
   memset(map,0,sizeof(map));
   memset(id,0,sizeof(id));

   for(int i=0;i<m;i++){
      int* pair = prerequisites[i];
      int x = pair[1], y = pair[0];
      id[y]++;
      map[x][y]=1;
   }

   // 1. 入度=0，则入队
   int count=0, q[n] , head=0 , tail=0;
   for(int i=0;i<n;i++){
      if(id[i]!=0) continue;
      q[tail++]=i;
      // 此处不执行Count++ !!!
   }

   // 2. 执行拓扑排序
   while(head<tail){
      int nodeSeq = q[head++];
      count++;
      // 3. 递减入度
      for(int i=0;i<n;i++){
          if(!map[nodeSeq][i]) continue;
          if(--id[i]==0) q[tail++]=i;   
      }
   }

   // 4. 判断是否可以得到拓扑序列
   return count==n;
}
typedef struct ListNode1{
    int val;
    struct ListNode1 *next;
}Node,*NodeP;

bool canFinish(int numCourses, int** prerequisites, int prerequisitesSize, 
int* prerequisitesColSize) {
   int n=numCourses,m=prerequisitesSize,id[n]; // id为入度数组
   NodeP vArr[n];
   for(int i=0;i<n;i++){
     vArr[i] = (NodeP)malloc(sizeof(Node)); // 哨兵节点
     vArr[i]->next = NULL; 
   }
   memset(id,0,sizeof(id));

   for(int i=0;i<m;i++){
      int* pair = prerequisites[i];
      int x = pair[1], y = pair[0];
      id[y]++;
      NodeP temp = (NodeP)malloc(sizeof(Node));
      temp->val = y;
      temp->next = vArr[x]->next;
      vArr[x]->next = temp;   
   }

   // 1. 入度=0，则入队
   int count=0, q[n] , head=0 , tail=0;
   for(int i=0;i<n;i++){
      if(id[i]!=0) continue;
      q[tail++]=i;
      // 此处不执行Count++ !!!
   }

   // 2. 执行拓扑排序
   while(head<tail){
      int nodeSeq = q[head++];
      count++;
      // 3. 递减入度
      for(NodeP t=vArr[nodeSeq]->next;t!=NULL;t=t->next){
          int tn = t->val;
          if(--id[tn]==0) q[tail++]=tn;   
      }
   }

   // 4. 判断是否可以得到拓扑序列
   return count==n;
}
