        NodeP temp = (NodeP)malloc(sizeof(Node));
        temp->val=y;
        // 如果不使用哨兵节点，那么顶点表数组需要单独处理第一个节点头插的情况
        if(vArr[x]) {
           temp->next=vArr[x]->next;
           vArr[x]->next=temp; // 头插        
        }else {
            temp->next=NULL;
            vArr[x]=temp;  
        }
    }

    // 输入k个待检验的拓扑序列
    int k;
    scanf("%d", &k);

    for (i = 0; i < k; i++) {
        int flag = 0;
        memcpy(d, indegree, sizeof(indegree));  // 复制入度数组
        // 输入待检验的拓扑序列
        for (j = 1; j <= n; j++) {
            scanf("%d", &ask[j]);
        }
        // 检查序列是否合法
        for (j = 1; j <= n; j++) {
            int x = ask[j];
            if (d[x] > 0) {
                flag = 1;  // 入度不为 0，序列非法
                break;
            }
            // 减少邻接顶点的入度
            NodeP node=vArr[x];
            for(;node!=NULL;node=node->next){
                d[node->val]--;
            }
        }

        // 输出非法序列的索引
        if (flag) {
            printf("%d ", i);
        }
    }

    return 0;
}
