#define N 100
#define MAX 1e5
int dis[N]; // 记录V0到V1~Vn中每个节点的最短路径(当前)
int visit[N]={0}; // 记录V0到哪些节点的最短路径已经被找到了
int map[N][N]={0}; // 存放无向图 
int n,m; // 一共多少个节点和边

int main(){
   // 声明迪杰斯特拉算法函数
   void dij(int);
   // 输入数据
   scanf("%d %d",&n,&m);
   // 初始化
   int i,j,x,y,val; 
   for(i=0;i<n;i++){
     for(j=0;j<n;j++){
        if(i==j) map[i][j] = 0;
        else map[i][j]=MAX;
     }
   }
   for(i=0;i<m;i++){
      scanf("%d %d %d",&x,&y,&val);
      // 大家如果想将下标设置为从0开始，那么一定要看看输入的数据下标是否为从0开始
      // 无向图要对称！！！
      map[x-1][y-1] = map[y-1][x-1] = val;
   }
   // 执行迪杰特斯拉函数
   dij(0);
   // 打印V0到其余节点的最短路径
   for(i=0;i<n;i++) printf("%d ",dis[i]);
   return 0;
}

void dij(int v0){
   int i,j,min,minIndex;
   // 1. 初始化dis数组
   for(i=0;i<n;i++) {
       dis[i] = map[v0][i];
       visit[i] = 0;
   }    
   visit[v0] = 1; 
   // 循环n-1轮,定位出V0到剩余n-1个节点的最短路径
   for(j=1;j<n;j++){
     min=MAX; 
     // 2. 定位到V0距离最近的节点，作为本轮选出的最短路径
     for(i=1;i<n;i++){
        if(visit[i] || dis[i] >= min) continue;
        min = dis[i];
        minIndex = i;
     }
     visit[minIndex]=1;
     // 3. V0尝试通过min节点发现到其他节点的最短路径
     for(i=1;i<n;i++){
        int update = dis[minIndex] + map[minIndex][i];
        if(visit[i] || dis[i] <= update) continue;
        dis[i] = update;
     }
   }
}

