      for(i=0;i<n;i++){
        for(j=0;j<n;j++){
           // 判断i到j的路径，能否由i到k,k到j缩短
           int update = map[i][k] + map[k][j];
           if(update >= map[i][j]) continue;
           map[i][j] = update;
        }
      }
   }
   // 打印输出V0到V1~Vn的最短路径
   for(i=0;i<n;i++) printf("%d ",map[0][i]);
