bool canFinish(int numCourses, int** prerequisites, int prerequisitesSize, 
int* prerequisitesColSize) {
   int n=numCourses,m=prerequisitesSize,id[n]; // id为入度数组
   int map[n][n];
   memset(map,0,sizeof(map));
   memset(id,0,sizeof(id));

   for(int i=0;i<m;i++){
      int* pair = prerequisites[i];
      int x = pair[1], y = pair[0];
      id[y]++;
      map[x][y]=1;
   }

   // 1. 入度=0，则入队
   int count=0, q[n] , head=0 , tail=0;
   for(int i=0;i<n;i++){
      if(id[i]!=0) continue;
      q[tail++]=i;
      // 此处不执行Count++ !!!
   }

   // 2. 执行拓扑排序
   while(head<tail){
      int nodeSeq = q[head++];
      count++;
      // 3. 递减入度
      for(int i=0;i<n;i++){
          if(!map[nodeSeq][i]) continue;
          if(--id[i]==0) q[tail++]=i;   
      }
   }

   // 4. 判断是否可以得到拓扑序列
   return count==n;
}
