int indegree[N], d[N];           // 前者存放入度, 后者copy
int ask[N];                      // 存放某一个待验证的拓扑序列

int main() {
    int i, j, n, m;
    scanf("%d %d", &n, &m);
    NodeP vArr[N]; // 顶点表
    memset(vArr,0,sizeof(vArr));

    // 输入边并构建邻接表
    for (i = 1; i <= m; i++) {
        int x, y;  // x --> y
        scanf("%d %d", &x, &y);
        indegree[y]++;  // y 的入度加一
        NodeP temp = (NodeP)malloc(sizeof(Node));
        temp->val=y;
        // 如果不使用哨兵节点，那么顶点表数组需要单独处理第一个节点头插的情况
        if(vArr[x]) {
           temp->next=vArr[x]->next;
           vArr[x]->next=temp; // 头插        
        }else {
            temp->next=NULL;
            vArr[x]=temp;  
        }
    }

    // 输入k个待检验的拓扑序列
    int k;
    scanf("%d", &k);

    for (i = 0; i < k; i++) {
        int flag = 0;
        memcpy(d, indegree, sizeof(indegree));  // 复制入度数组
        // 输入待检验的拓扑序列
        for (j = 1; j <= n; j++) {
            scanf("%d", &ask[j]);
        }
        // 检查序列是否合法
        for (j = 1; j <= n; j++) {
            int x = ask[j];
            if (d[x] > 0) {
                flag = 1;  // 入度不为 0，序列非法
                break;
            }
            // 减少邻接顶点的入度
            NodeP node=vArr[x];
            for(;node!=NULL;node=node->next){
                d[node->val]--;
            }
        }

        // 输出非法序列的索引
        if (flag) {
            printf("%d ", i);
        }
    }

    return 0;
}
