   *returnSize = n;
   NodeP vArr[n];
   for(int i=0;i<n;i++){
     vArr[i] = (NodeP)malloc(sizeof(Node)); // 哨兵节点
     vArr[i]->next = NULL; 
   }
   memset(id,0,sizeof(id));

   for(int i=0;i<m;i++){
      int* pair = prerequisites[i];
      int x = pair[1], y = pair[0];
      id[y]++;
      NodeP temp = (NodeP)malloc(sizeof(Node));
      temp->val = y;
      temp->next = vArr[x]->next;
      vArr[x]->next = temp;   
   }

   // 1. 入度=0，则入队
   int count=0 , *res , q[n] , head=0 , tail=0;
   res = (int*)malloc(sizeof(int)*n);
   for(int i=0;i<n;i++){
      if(id[i]!=0) continue;
      q[tail++]=i;
   }

   // 2. 执行拓扑排序
   while(head<tail){
      int nodeSeq = q[head++];
      res[count++]=nodeSeq;
      // 3. 递减入度
      for(NodeP t=vArr[nodeSeq]->next;t!=NULL;t=t->next){
          int tn = t->val;
          if(--id[tn]==0) q[tail++]=tn;   
      }
   }

   if(count!=n) *returnSize=0; // 别忘记没有解的情况！！！ 
   return res;
}

