// 螺旋矩阵(蛇形填数字)
int* spiralOrder(int** matrix, int matrixSize, int* matrixColSize, int* 
returnSize) {
    int* f(int**,int,int);
    *returnSize =  matrixSize*matrixColSize[0];
    return f(matrix,matrixSize,matrixColSize[0]);
}

int* f(int** arr, int n,int c) {
    int* res = (int*)malloc(sizeof(int) * n * c);
    int index = 0;
    int top = 0, down = n - 1, left = 0, right = c-1; // 指向上下左右边界的指针

    // 按照右、下、左、上顺序螺旋遍历
    while (top <= down && left <= right) {
        // 1. 沿top指向行向右遍历
        for (int i = left; i <= right; i++) res[index++] = arr[top][i];
        if (++top > down) break;

        // 2. 沿right指向列向下遍历
        for (int i = top; i <= down; i++) res[index++] = arr[i][right];
        if (--right < left) break;

        // 3. 沿down指向行向左遍历
        for (int i = right; i >= left; i--) res[index++] = arr[down][i];
        if (--down < top) break;

        // 4. 沿left指向列向上遍历
        for (int i = down; i >= top; i--) res[index++] = arr[i][left];
        if (++left > right) break;
    }

    return res;
}
